attempts.cypher:
MATCH (source:PlantItem {tag: 'P-44001A'})
MATCH (v:Valve), (e:Equipment)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'E-53401'}), (b:PlantItem {tag: 'V-53401'}), (v:Valve)
WHERE v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

