MATCH (pump:PlantItem {tag: 'P-38001A'})
MATCH (pump)-[:line_to*1..]->(v:Valve)
WHERE NOT EXISTS {
  MATCH (pump)-[:line_to*1..]->(e:Equipment)
  WHERE e <> v
    AND EXISTS { (pump)-[:line_to*1..]->(e) }
    AND NOT EXISTS {
      MATCH (pump)-[:line_to*1..]->(v2:PlantItem)
      WHERE v2 <> v
    }
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag

